// Decide whether to write a new draft now (one automatic draft per weekday; manual /new allowed up to 4 a day)
const store = $getWorkflowStaticData('global');
const inp = $input.first().json || {};
const viaBot = $('Handle content bot').isExecuted && $('Handle content bot').first().json.kind === 'new';
const manual = !!(inp.query || inp.headers) || viaBot;
const today = new Date().toLocaleDateString('en-CA', { timeZone: 'Asia/Karachi' });
const day = store.day && store.day.date === today ? store.day : { date: today, auto: 0, manual: 0 };
const pending = Object.values(store.drafts || {}).filter((d) => d.status === 'waiting').length;
let why = null;
if (store.paused) why = 'drafting is paused (send /resume)';
else if (!manual && day.auto >= 1) why = 'already drafted today';
else if (!manual && pending >= 2) why = 'two drafts are still waiting for your approval';
else if (manual && day.manual >= 4) why = 'manual limit reached for today (4)';
if (why) return [{ json: { ok: false, manual, why } }];
if (manual) day.manual++; else day.auto++;
store.day = day;
return [{ json: { ok: true, manual } }];

// Collect fresh, relevant stories from the feeds (no repeats) and ask Gemini to pick the best one for small businesses
const store = $getWorkflowStaticData('global');
const FEEDS = ['Feed – Google News (AI marketing)', 'Feed – Google News (automation)', 'Feed – Zapier blog', 'Feed – HubSpot marketing', 'Feed – Search Engine Journal'];
const used = new Set(store.used || []);
const norm = (t) => String(t || '').toLowerCase().replace(/[^a-z0-9 ]/g, '').replace(/\s+/g, ' ').trim().slice(0, 80);
const REL = /\b(ai|automat\w*|chatgpt|gpt|gemini|claude|copilot|agents?|chatbots?|workflows?|no-code|zapier|small business(es)?|smbs?|marketing|content|email|seo|customer service|crm|productivity)\b/i;
const items = [];
for (const f of FEEDS) {
  let arr = [];
  try { arr = $(f).all().map((i) => i.json); } catch (e) { arr = []; }
  for (const it of arr) {
    if (!it || !it.title || it.error) continue;
    const d = Date.parse(it.isoDate || it.pubDate || 0);
    const age = (Date.now() - d) / 864e5;
    if (!(age >= -1 && age <= 6)) continue;
    const link = it.link || it.guid;
    if (!link || used.has(link) || used.has(norm(it.title))) continue;
    const text = `${it.title} ${it.contentSnippet || ''}`;
    if (!REL.test(text)) continue;
    const isGN = /news\.google\.com/.test(link);
    const gnSource = (String(it.title).match(/ - ([^-]+)$/) || [])[1];
    items.push({ title: isGN ? String(it.title).replace(/ - [^-]+$/, '').trim() : String(it.title).trim(), link, source: (isGN ? gnSource : f.replace('Feed – ', '')) || 'Google News', date: new Date(d).toISOString().slice(0, 10), snippet: String(it.contentSnippet || '').replace(/\s+/g, ' ').slice(0, 400), isGN });
  }
}
const seenT = new Set();
const cand = [];
for (const c of items.sort((a, b) => b.date.localeCompare(a.date))) { const k = norm(c.title); if (seenT.has(k)) continue; seenT.add(k); cand.push(c); if (cand.length >= 18) break; }
if (!cand.length) return [{ json: { none: true, why: 'no fresh, relevant stories in the feeds today' } }];
const KEYS = ['writing', 'chatbot', 'email', 'social', 'workflow', 'analytics', 'ecommerce', 'seo', 'booking', 'productivity'];
const recent = (store.recentImages || []).slice(0, 3);
const prompt = `You are the editor of the "AI & Automation" section on Content Writing UK, a UK content-writing agency's blog. Readers are small business owners and marketers.
Pick the ONE story below that makes the most useful, practical article for them about using AI or automation in content, marketing, customer service or daily operations. Prefer practical how-to angles over funding news, and avoid stories that only matter to big tech companies.
Choose the best featured image key from: ${KEYS.join(', ')}${recent.length ? ` (if another key fits equally well, avoid these recent ones: ${recent.join(', ')})` : ''}.
Return only JSON: {"index": <number>, "angle": "<one sentence: the practical angle for small businesses>", "image": "<key>", "focus_keyword": "<2-4 word SEO keyword>"}
Stories: ${JSON.stringify(cand.map((c, i) => ({ i, title: c.title, source: c.source, date: c.date, snippet: c.snippet })))}`;
return [{ json: { cand, geminiBody: { contents: [{ role: 'user', parts: [{ text: prompt }] }], generationConfig: { temperature: 0.4, responseMimeType: 'application/json' } } } }];

// Read Gemini's choice (fallback: the newest story)
const p = $('Pick candidates').first().json;
let a = {};
try { const g = $input.first().json; a = JSON.parse(g.candidates[0].content.parts.map((x) => x.text || '').join('').replace(/^```(json)?\s*|```\s*$/g, '').trim()); } catch (e) { a = {}; }
const KEYS = ['writing', 'chatbot', 'email', 'social', 'workflow', 'analytics', 'ecommerce', 'seo', 'booking', 'productivity'];
const story = p.cand[Number.isInteger(a.index) && p.cand[a.index] ? a.index : 0];
return [{ json: { story, angle: String(a.angle || 'What this means for small businesses, and practical steps to try').slice(0, 240), image: KEYS.includes(a.image) ? a.image : 'workflow', focus: String(a.focus_keyword || 'AI for small business').slice(0, 60), fetchUrl: story.isGN ? '' : story.link } }];

// Build the article prompt (new draft, or a rewrite of an existing draft)
const store = $getWorkflowStaticData('global');
let ctx, rewrite = null, sourceText = '';
if ($('Handle content bot').isExecuted && $('Handle content bot').first().json.kind === 'rewrite') {
  const h = $('Handle content bot').first().json;
  const d = store.drafts[h.postId];
  ctx = { story: d.story, angle: d.angle, image: d.image, focus: d.focus };
  rewrite = { postId: h.postId, prevTitle: d.title };
  sourceText = d.sourceText || '';
} else {
  ctx = $('Read pick').first().json;
  if ($('Fetch article').isExecuted) {
    const html = String(($('Fetch article').first().json || {}).data || '');
    const main = (html.match(/<article[\s\S]*?<\/article>/i) || html.match(/<main[\s\S]*?<\/main>/i) || [html])[0];
    sourceText = main.replace(/<(script|style|nav|footer|header|aside|form)[\s\S]*?<\/\1>/gi, ' ').replace(/<\/(p|h[1-6]|li|blockquote)>/gi, '\n').replace(/<[^>]+>/g, ' ').replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/&#8217;|&rsquo;/g, "'").replace(/[ \t]+/g, ' ').split('\n').map((s) => s.trim()).filter((s) => s.length > 40).join('\n').slice(0, 6000);
  }
}
const s = ctx.story;
const prompt = `You write for the "AI & Automation" section of Content Writing UK (contentwritinguk.com), a UK content-writing agency. Audience: UK small business owners and marketers, not technical people.
Write an ORIGINAL, genuinely useful article inspired by the story below, using this angle: ${ctx.angle}
Rules:
- LENGTH: 850-1,050 words of article text (this matters: count carefully; each <h2> section should be 140-220 words). British English, plain and friendly expert tone, short paragraphs, no hype, no emojis, no exclamation marks.
- Use only facts that appear in the source material below; never invent statistics, quotes, prices, names or dates. If a fact is not in the source, keep the point general. Credit the source by name once where you use its facts.
- Structure: an engaging intro (2-3 short paragraphs, no heading), then 3-5 sections with <h2> headings (<h3> optional), at least one practical list (<ul> or <ol>) of steps a small business could try this week, and a short final section headed "The bottom line".
- Once, near the end and only where it fits naturally, note that AI output still needs a human editor's touch and that Content Writing UK's writers can help. No hard sell.
- HTML only, using just these tags: h2, h3, p, ul, ol, li, strong, em, blockquote. No h1, no links, no inline styles, no images.
- Do not copy sentences from the source.
${rewrite ? `- This is a REWRITE: use a clearly different title and structure from the previous version (previous title: "${rewrite.prevTitle}").\n` : ''}Also write:
- title: max 65 characters, includes the focus keyword "${ctx.focus}" naturally, no clickbait.
- seo_title: max 60 characters. meta_description: 140-158 characters. slug: 3-6 lowercase words joined by hyphens. excerpt: 1-2 sentences.
- linkedin_post: 80-170 words in Aqib's voice (first person; he runs Content Writing UK and an automation studio). A strong first-line hook, 2-4 short paragraphs or a short list, one practical takeaway, end with a question that invites comments, then 3 relevant hashtags. Do not include any link (it is added automatically).
- x_post: max 260 characters, at most 1 hashtag.
- instagram_caption: 60-120 words, then 5 hashtags.
Return only JSON: {"title":"","seo_title":"","meta_description":"","slug":"","excerpt":"","html":"","linkedin_post":"","x_post":"","instagram_caption":""}
Story: ${s.title} (${s.source}, ${s.date})
Snippet: ${s.snippet}
Source text (may be partial or empty): ${sourceText || '(not available - rely on the title and snippet only and keep facts general)'}`;
return [{ json: { ...ctx, rewrite, sourceText, geminiBody: { contents: [{ role: 'user', parts: [{ text: prompt }] }], generationConfig: { temperature: rewrite ? 0.85 : 0.6, responseMimeType: 'application/json', maxOutputTokens: 8000 } } } }];

// Parse the article, clean the HTML, add sources + note, and prepare the WordPress draft
const SITE = 'https://contentwritinguk.com';
const CAT = 68;
const MEDIA = { analytics: 5059, booking: 5060, chatbot: 5061, ecommerce: 5062, email: 5063, productivity: 5064, seo: 5065, social: 5066, workflow: 5067, writing: 5068 };
const IMG = (k) => `${SITE}/wp-content/uploads/2026/11/cwuk-ai-${k}.png`;
const w = $('Writer prompt').first().json;
let a = {};
try { const g = ($input.first().json && $input.first().json.candidates) ? $input.first().json : ($('Gemini – write post').first().json || {}); a = JSON.parse(g.candidates[0].content.parts.map((x) => x.text || '').join('').replace(/^```(json)?\s*|```\s*$/g, '').trim()); } catch (e) { a = {}; }
if (!a.title || !a.html) return [{ json: { failed: true, why: 'The AI did not return a usable article (try /new again).' } }];
const ALLOWED = ['h2', 'h3', 'p', 'ul', 'ol', 'li', 'strong', 'em', 'blockquote'];
let html = String(a.html).replace(/<(script|style)[\s\S]*?<\/\1>/gi, '').replace(/<\/?([a-z0-9]+)(\s[^>]*)?>/gi, (m, t) => (ALLOWED.includes(t.toLowerCase()) ? m.replace(/\s[^>]*>/, '>') : '')).replace(/\n{3,}/g, '\n\n').trim();
const esc = (t) => String(t).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const s = w.story;
html += `\n<h2>Source</h2>\n<ul><li><a href="${esc(s.link)}" target="_blank" rel="nofollow noopener">${esc(s.title)}</a> (${esc(s.source)}, ${esc(s.date)})</li></ul>\n<p><em>This article was prepared with the help of AI and reviewed by the Content Writing UK team before publishing.</em></p>`;
const words = html.replace(/<[^>]+>/g, ' ').split(/\s+/).filter(Boolean).length;
const slug = String(a.slug || a.title).toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '').split('-').slice(0, 8).join('-');
const body = { title: String(a.title).slice(0, 90), content: html, status: 'draft', excerpt: String(a.excerpt || a.meta_description || '').slice(0, 300), slug, categories: [CAT], featured_media: MEDIA[w.image] || MEDIA.workflow };
return [{ json: { wpUrl: `${SITE}/wp-json/wp/v2/posts${w.rewrite ? '/' + w.rewrite.postId : ''}`, wpBody: body, words, seoTitle: String(a.seo_title || a.title).slice(0, 60), meta: String(a.meta_description || a.excerpt || '').slice(0, 160), linkedin: String(a.linkedin_post || '').trim(), x: String(a.x_post || '').trim(), ig: String(a.instagram_caption || '').trim() } }];

// Remember the draft and build the Telegram approval card
const SITE = 'https://contentwritinguk.com';
const CAT = 68;
const MEDIA = { analytics: 5059, booking: 5060, chatbot: 5061, ecommerce: 5062, email: 5063, productivity: 5064, seo: 5065, social: 5066, workflow: 5067, writing: 5068 };
const IMG = (k) => `${SITE}/wp-content/uploads/2026/11/cwuk-ai-${k}.png`;
const store = $getWorkflowStaticData('global');
const w = $('Writer prompt').first().json;
const p = $('Assemble post').first().json;
const r = $('WP – save draft').first().json || {};
if (r.error || !r.id) return [{ json: { failed: true, text: `Could not save the draft in WordPress: ${String((r.error && (r.error.message || r.error.description)) || 'no post id').slice(0, 200)}` } }];
const v = Math.random().toString(36).slice(2, 6);
store.drafts = store.drafts || {};
store.drafts[r.id] = { id: r.id, v, status: 'waiting', title: p.wpBody.title, story: w.story, angle: w.angle, image: w.image, focus: w.focus, sourceText: String(w.sourceText || '').slice(0, 4000), linkedin: p.linkedin, x: p.x, ig: p.ig, excerpt: p.wpBody.excerpt, words: p.words, created: new Date().toISOString() };
store.used = [w.story.link, String(w.story.title).toLowerCase().replace(/[^a-z0-9 ]/g, '').replace(/\s+/g, ' ').trim().slice(0, 80), ...(store.used || [])].slice(0, 400);
store.recentImages = [w.image, ...(store.recentImages || [])].slice(0, 5);
const ids = Object.keys(store.drafts).sort((a, b) => Number(b) - Number(a)); ids.slice(30).forEach((k) => { if (store.drafts[k].status !== 'waiting') delete store.drafts[k]; });
const card = [
  `${w.rewrite ? 'REWRITTEN' : 'New'} blog draft – AI & Automation (${p.words} words${p.words < 650 ? ', a bit short: tap Rewrite for a longer version' : ''})`,
  `Title: ${p.wpBody.title}`,
  `Based on: ${w.story.title} (${w.story.source}, ${w.story.date})`,
  `Preview (you must be logged in to WordPress): ${SITE}/?p=${r.id}&preview=true`,
  `SEO: ${p.seoTitle} | ${p.meta}`,
  '', 'LinkedIn post (goes out when you tap Publish):', p.linkedin,
  '', 'X draft:', p.x,
  '', 'Instagram draft:', p.ig.slice(0, 600),
  '', 'Reply to this message with new text to replace the LinkedIn post.', `Ref D${r.id}`,
].join('\n').slice(0, 4000);
return [{ json: { failed: false, postId: r.id, cb: `${r.id}:${v}`, card, photo: IMG(w.image), caption: `${p.wpBody.title}\n\n${p.wpBody.excerpt}`.slice(0, 1000) } }];

// RixDigi Content bot: Publish / Rewrite / Skip buttons, LinkedIn text replies, and /new /status /pause /resume (Aqib's chat only)
const OWNER = Number('YOUR_TELEGRAM_CHAT_ID'); // your own Telegram chat id
const store = $getWorkflowStaticData('global');
const u = $input.first().json || {};
const when = new Date().toLocaleString('en-GB', { timeZone: 'Asia/Karachi', dateStyle: 'short', timeStyle: 'short' });
const cq = u.callback_query;
const msg = u.message;
const drafts = store.drafts || {};
if (cq) {
  if (Number(cq.from && cq.from.id) !== OWNER || !cq.message) return [{ json: { kind: 'ignore' } }];
  const [act, id, v] = String(cq.data || '').split(':');
  const base = { kind: 'callback', queryId: cq.id, chatId: cq.message.chat.id, messageId: cq.message.message_id, original: String(cq.message.text || '').slice(0, 3600) };
  const d = drafts[id];
  if (!d || d.v !== v) return [{ json: { ...base, act: 'none', answer: 'Out of date', status: 'OUT OF DATE: use the newest card for this draft.' } }];
  if (d.status !== 'waiting') return [{ json: { ...base, act: 'none', answer: 'Already handled', status: `Already handled (${d.status}).` } }];
  if (act === 'cp') { d.status = 'publishing'; return [{ json: { ...base, act: 'publish', postId: Number(id), answer: 'Publishing', status: `PUBLISHING ${when}…` } }]; }
  if (act === 'cr') { d.status = 'rewriting'; return [{ json: { ...base, act: 'rewrite', kind: 'rewrite', postId: Number(id), answer: 'Rewriting', status: `REWRITE requested ${when}. A new card follows in a minute.` } }]; }
  if (act === 'cs') { d.status = 'skipped'; return [{ json: { ...base, act: 'skip', postId: Number(id), answer: 'Skipped', status: `SKIPPED ${when}. The draft was moved to the WordPress bin.` } }]; }
  return [{ json: { kind: 'ignore' } }];
}
if (msg && typeof msg.text === 'string') {
  if (Number(msg.chat && msg.chat.id) !== OWNER) return [{ json: { kind: 'ignore' } }];
  const t = msg.text.trim();
  const rt = msg.reply_to_message && String(msg.reply_to_message.text || '');
  const m = rt && rt.match(/Ref D(\d+)/);
  if (m && !t.startsWith('/')) {
    const d = drafts[m[1]];
    if (!d || d.status !== 'waiting') return [{ json: { kind: 'reply', chatId: OWNER, text: 'That draft is no longer waiting, so nothing was changed.' } }];
    d.linkedin = t;
    return [{ json: { kind: 'reply', chatId: OWNER, text: 'Got it. This text will be the LinkedIn post when you tap Publish on the card.' } }];
  }
  const c = t.toLowerCase();
  if (c.startsWith('/pause')) { store.paused = true; return [{ json: { kind: 'reply', chatId: OWNER, text: 'Paused. No new drafts until you send /resume.' } }]; }
  if (c.startsWith('/resume')) { store.paused = false; return [{ json: { kind: 'reply', chatId: OWNER, text: 'Resumed. The next draft comes on the next weekday morning, or send /new.' } }]; }
  if (c.startsWith('/new')) return [{ json: { kind: 'new', chatId: OWNER, text: 'Writing a new draft now. The card arrives in about a minute.' } }];
  const ds = Object.values(drafts);
  const pub = ds.filter((d) => d.status === 'published');
  return [{ json: { kind: 'reply', chatId: OWNER, text: [`RixDigi Content – contentwritinguk.com (AI & Automation)`, `${store.paused ? 'PAUSED' : 'Running'}: a new draft every weekday at 09:23 (PKT).`, `Waiting for you: ${ds.filter((d) => d.status === 'waiting').length} · published: ${pub.length} · skipped: ${ds.filter((d) => d.status === 'skipped').length}`, pub[0] ? `Latest: ${pub.sort((a, b) => String(b.publishedAt).localeCompare(String(a.publishedAt)))[0].link}` : '', '', 'Commands: /new /status /pause /resume'].filter((x) => x !== '').join('\n') } }];
}
return [{ json: { kind: 'ignore' } }];

// What goes to LinkedIn: Aqib's approved text + the live article as a link card with the featured image
const SITE = 'https://contentwritinguk.com';
const CAT = 68;
const MEDIA = { analytics: 5059, booking: 5060, chatbot: 5061, ecommerce: 5062, email: 5063, productivity: 5064, seo: 5065, social: 5066, workflow: 5067, writing: 5068 };
const IMG = (k) => `${SITE}/wp-content/uploads/2026/11/cwuk-ai-${k}.png`;
const store = $getWorkflowStaticData('global');
const h = $('Handle content bot').first().json;
const d = store.drafts[h.postId];
const wp = $input.first().json || {};
return [{ json: { text: d.linkedin, url: wp.link || `${SITE}/?p=${h.postId}`, title: d.title, description: String(d.excerpt || '').slice(0, 200), imageUrl: IMG(d.image), ok: !wp.error && wp.status === 'publish' } }];

// Record the publish + LinkedIn result, prepare the calendar rows and the Telegram note
const store = $getWorkflowStaticData('global');
const h = $('Handle content bot').first().json;
const d = store.drafts[h.postId];
const wp = $('WP – publish').first().json || {};
const li = $('LinkedIn – share').first().json || {};
if (wp.error || wp.status !== 'publish') {
  d.status = 'waiting';
  return [{ json: { ok: false, text: `Publishing failed: ${String((wp.error && (wp.error.message || wp.error.description)) || wp.status || 'unknown').slice(0, 200)}. The draft is still waiting; tap Publish again on the card later.`, rows: [] } }];
}
const liOk = !li.error && (li.urn || li.id || li.success !== false);
d.status = 'published'; d.link = wp.link; d.publishedAt = new Date().toISOString(); d.linkedinOk = liOk;
const uk = new Date().toLocaleString('en-GB', { timeZone: 'Europe/London', dateStyle: 'short', timeStyle: 'short' });
const today = new Date().toISOString().slice(0, 10);
const rows = [
  [uk, d.story.title, 'Blog (contentwritinguk.com)', 'Published', today, d.title, String(d.words), wp.link, `D${h.postId}`],
  [uk, d.story.title, 'LinkedIn', liOk ? 'Published' : 'Failed', today, d.linkedin, String(d.linkedin.length), wp.link, `D${h.postId}`],
  [uk, d.story.title, 'X', 'Draft', today, d.x, String(d.x.length), wp.link, `D${h.postId}`],
  [uk, d.story.title, 'Instagram', 'Draft', today, d.ig, String(d.ig.length), wp.link, `D${h.postId}`],
];
const liErr = li.error ? String(li.error.message || li.error.description || li.error).slice(0, 160) : '';
return [{ json: { ok: true, rows, text: `Published: ${wp.link}\nLinkedIn: ${liOk ? 'posted to your profile' : 'FAILED (' + liErr + ') – copy the text from the card and post it by hand'}.\nX and Instagram drafts are saved in the content calendar.` } }];
